-- field: allDocuments
SELECT jsonb_build_object('nodes', coalesce(jsonb_agg(__s_8.ndata ORDER BY __s_8.__rn ASC) FILTER (WHERE __s_8.__rn <= $2), '[]'::jsonb)) AS data
FROM (
  SELECT jsonb_build_object('id', __t_1."id", 'slug', __t_1."slug", 'search', __t_1."search", 'attrs', "ext".hstore_to_jsonb(__t_1."attrs"), 'path', __t_1."path", 'paths', to_jsonb(__t_1."paths"), 'ip', __t_1."ip", 'net', __t_1."net", 'during', (SELECT jsonb_build_object('start', CASE WHEN lower(__rg_2.r) IS NULL THEN NULL ELSE jsonb_build_object('value', lower(__rg_2.r), 'inclusive', lower_inc(__rg_2.r)) END, 'end', CASE WHEN upper(__rg_2.r) IS NULL THEN NULL ELSE jsonb_build_object('value', upper(__rg_2.r), 'inclusive', upper_inc(__rg_2.r)) END) FROM (SELECT __t_1."during" AS r) AS __rg_2 WHERE __rg_2.r IS NOT NULL), 'span', (SELECT jsonb_build_object('__typename', 'IntRange'::text, 'lower', CASE WHEN lower(__rg_3.r) IS NULL THEN NULL ELSE jsonb_build_object('value', lower(__rg_3.r)) END, 'end', CASE WHEN upper(__rg_3.r) IS NULL THEN NULL ELSE jsonb_build_object('inclusive', upper_inc(__rg_3.r), '__typename', 'IntRangeBound'::text, 'value', upper(__rg_3.r)) END) FROM (SELECT __t_1."span" AS r) AS __rg_3 WHERE __rg_3.r IS NOT NULL), 'avail', (SELECT CASE WHEN __mr_4.m IS NULL THEN NULL ELSE coalesce((SELECT jsonb_agg(jsonb_build_object('start', CASE WHEN lower(__rg_5.r) IS NULL THEN NULL ELSE jsonb_build_object('value', lower(__rg_5.r), 'inclusive', lower_inc(__rg_5.r)) END, 'end', CASE WHEN upper(__rg_5.r) IS NULL THEN NULL ELSE jsonb_build_object('value', upper(__rg_5.r), 'inclusive', upper_inc(__rg_5.r)) END) ORDER BY __rg_5.r) FROM unnest(__mr_4.m) AS __rg_5(r)), '[]'::jsonb) END FROM (SELECT __t_1."avail" AS m) AS __mr_4), 'price', (SELECT jsonb_build_object('start', CASE WHEN lower(__rg_6.r) IS NULL THEN NULL ELSE jsonb_build_object('value', (lower(__rg_6.r))::text) END, 'end', CASE WHEN upper(__rg_6.r) IS NULL THEN NULL ELSE jsonb_build_object('value', (upper(__rg_6.r))::text) END) FROM (SELECT __t_1."price" AS r) AS __rg_6 WHERE __rg_6.r IS NOT NULL), 'window', (SELECT jsonb_build_object('start', CASE WHEN lower(__rg_7.r) IS NULL THEN NULL ELSE jsonb_build_object('value', lower(__rg_7.r)) END, 'end', CASE WHEN upper(__rg_7.r) IS NULL THEN NULL ELSE jsonb_build_object('value', upper(__rg_7.r)) END) FROM (SELECT "public"."documents_window"("d" => ROW(__t_1."id", __t_1."title", __t_1."slug", __t_1."search", __t_1."attrs", __t_1."path", __t_1."label", __t_1."paths", __t_1."during", __t_1."span", __t_1."avail", __t_1."price", __t_1."ip", __t_1."net", __t_1."notes")::"public"."documents") AS r) AS __rg_7 WHERE __rg_7.r IS NOT NULL)) AS ndata, row_number() OVER (ORDER BY __t_1."id" ASC) AS __rn
  FROM "public"."documents" AS __t_1
  ORDER BY __t_1."id" ASC
  LIMIT $1
) AS __s_8
GROUP BY ()
